import{_ as t,o as i,c as s,ai as a}from"./chunks/framework.C33Uq6m-.js";const g=JSON.parse('{"title":"Fill-in-the-Middle Playground","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/fim.md","filePath":"en/guide/fim.md"}'),o={name:"en/guide/fim.md"};function n(l,e,r,h,d,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="fill-in-the-middle-playground" tabindex="-1">Fill-in-the-Middle Playground <a class="header-anchor" href="#fill-in-the-middle-playground" aria-label="Permalink to &quot;Fill-in-the-Middle Playground&quot;">​</a></h1><p>The <strong>FIM Playground</strong> is a small, focused page for testing <strong>code-completion-style</strong> generation. You provide a <strong>prefix</strong> (code before the cursor) and a <strong>suffix</strong> (code after the cursor), and the model fills the gap in between.</p><p><strong>Sidebar item:</strong> Code Completion (under Tool Workshop) <strong>Route:</strong> <code>/fim</code><strong>Added in:</strong> v0.4.7 (May 2026)</p><h2 id="what-is-fill-in-the-middle" tabindex="-1">What is fill-in-the-middle? <a class="header-anchor" href="#what-is-fill-in-the-middle" aria-label="Permalink to &quot;What is fill-in-the-middle?&quot;">​</a></h2><p>Most chat APIs only support left-to-right generation: you give a prompt, the model continues from where you left off. <strong>FIM</strong> is different — the model sees what comes <em>after</em> the gap as well, and writes content that fits naturally between the two anchors.</p><p>This is what powers tools like GitHub Copilot&#39;s mid-line suggestions and Cursor&#39;s &quot;tab completion.&quot; Several Ollama-served models support it natively:</p><ul><li><strong>Qwen2.5-Coder</strong> (all sizes)</li><li><strong>CodeLlama</strong> (the <code>-code</code> variants)</li><li><strong>Codestral</strong></li><li><strong>DeepSeek-Coder</strong></li><li><strong>StarCoder</strong></li></ul><p>Ollama exposes FIM through a <code>suffix</code> field on the <code>/api/generate</code> endpoint. LLMxRay surfaces this in the FIM Playground page.</p><h2 id="using-the-page" tabindex="-1">Using the page <a class="header-anchor" href="#using-the-page" aria-label="Permalink to &quot;Using the page&quot;">​</a></h2><ol><li>Pick a model from the dropdown — coding-capable models are listed first under &quot;Coding models (FIM-capable)&quot;.</li><li>Type your <strong>prefix</strong> (the code that comes before the cursor) in the left textarea.</li><li>Type your <strong>suffix</strong> (the code that comes after the cursor) in the right textarea.</li><li>Click <strong>Generate</strong>.</li></ol><p>The model streams the missing middle in real time. After generation completes you also see a <strong>Stitched preview</strong> — the prefix, the generated middle (highlighted in accent color), and the suffix rendered as one continuous block, so you can read the whole result as it would appear in your editor.</p><h2 id="metrics" tabindex="-1">Metrics <a class="header-anchor" href="#metrics" aria-label="Permalink to &quot;Metrics&quot;">​</a></h2><p>When generation finishes, four metric cards appear below the output:</p><ul><li><strong>Total duration</strong> — wall-clock time from request to the final token</li><li><strong>Model load</strong> — how long Ollama spent loading the model into memory (0 ms for warm starts)</li><li><strong>Generated tokens</strong> — count of tokens the model produced for the middle</li><li><strong>Speed</strong> — tokens per second</li></ul><h2 id="if-the-model-doesn-t-support-fim" tabindex="-1">If the model doesn&#39;t support FIM <a class="header-anchor" href="#if-the-model-doesn-t-support-fim" aria-label="Permalink to &quot;If the model doesn&#39;t support FIM&quot;">​</a></h2><p>If you pick a non-coding model, the page warns you up front. If you try anyway, Ollama returns a clear error: <code>qwen2.5:3b does not support insert</code> (or similar, with the model name in place). The page surfaces this in the output area without crashing.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>The page calls <code>/api/generate</code> with the new <code>suffix</code> field that Ollama exposes:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;qwen2.5-coder:7b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;prompt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;def fibonacci(n):</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    if n &lt;= 1:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        return n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;suffix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">print(fibonacci(10))&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The streamed NDJSON response is parsed the same way as a regular chat — one JSON object per line, accumulating <code>response</code> deltas until <code>done: true</code>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./chat-diagnostics.html">Chat Diagnostics</a> for general chat</li><li><a href="./tool-workshop.html">Tool Workshop</a> for building agentic tools</li></ul>`,22)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
